from scipy.optimize import least_squares
def g(p):
    return p[0]*P**2 + p[1]*np.log(1+p[2]*P)*t + p[3]*P + p[4]*np.sin(p[5]*t)+p[6]
best=None
for w in np.linspace(0.2,3,29):
    for c in [0.5,2]:
        try:
            r=least_squares(lambda p: g(p)-dP_dt, np.r_[-0.5,2,c,0.5,1,w,0.0])
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
print(np.round(best.x,4), np.mean((dP_dt-g(best.x))**2)/np.var(dP_dt))

