names=['P2','P','t','t2','Pt','1','Pt2','P2t','sin t','cos t','exp-t','Plogt','tlogP','P3','sqrtP','t3','1/P','1/(1+P)','Pexp(-t)','tP2','P sin','P cos']
def basis(c):
    L=np.log(1+c*P)*t
    cols={'P2':P**2,'P':P,'t':t,'t2':t**2,'Pt':P*t,'1':np.ones_like(t),'Pt2':P*t**2,'P2t':P**2*t,'sin t':np.sin(t),'cos t':np.cos(t),'exp-t':np.exp(-t),'Plogt':P*np.log(t),'tlogP':t*np.log(P),'P3':P**3,'sqrtP':np.sqrt(P),'t3':t**3,'1/P':1/P,'1/(1+P)':1/(1+P),'Pexp(-t)':P*np.exp(-t),'tP2':t*P**2,'P sin':P*np.sin(t),'P cos':P*np.cos(t)}
    return L,cols
def fit(c,extra):
    L,cols=basis(c)
    X=np.c_[L,P**2]+0
    X=np.column_stack([L,P**2]+[cols[e] for e in extra])
    b,*_=np.linalg.lstsq(X,dP_dt,rcond=None)
    res=dP_dt-X@b
    return np.mean(res**2)/np.var(dP_dt), b
out=[]
for c in np.linspace(0.05,3,60):
    for k in [1,2]:
        for extra in itertools.combinations(names,k):
            e,b=fit(c,extra)
            out.append((e,c,extra))
out.sort(key=lambda x:x[0])
for o in out[:15]: print(o)

